// fontsBy("kufi") / fontsBy("display") → registry rows matching genre/role/mood text
window.fontsBy = q => FONT_REGISTRY.filter(f => (f.genre + " " + f.role + " " + f.mood + " " + f.family).toLowerCase().includes(q.toLowerCase()));
// preload strings for FILM.fonts: fontLoads(["Cairo","Amiri"]) → ["700 60px Cairo", ...]
window.fontLoads = fams => fams.flatMap(fam => { const f = FONT_REGISTRY.find(r => r.family === fam); if (!f) return []; return f.weights.map(w => `${w.split(" ").pop()} 60px "${fam}"`); });
